export const expandedTranslations = Object.fromEntries(['ta', 'gu', 'pa'].map((language, index) => {
  const result = {};
  for (const [path, values] of Object.entries(rows)) {
    const keys = path.split('.'); let node = result;
    for (const key of keys.slice(0, -1)) node = node[key] ||= {};
    node[keys.at(-1)] = values[index];
  }
  result.how.steps = steps.map(row => ({ title: row[index][0], desc: row[index][1] }));
  result.trust.items = [result.founder.proof, result.hero.t2, result.safety.card1Desc];
  result.training.steps = steps.map(row => ({ title: row[index][0], desc: row[index][1] }));
  result.faq.items = faqs.map(row => ({ q: row[index][0], a: row[index][1] }));
  return [language, result];
}));
